import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Color, DoubleSide, SRGBColorSpace } = THREE;

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors =
    config.intent?.visualSpec?.colors ??
    { ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10' };
  const C = {
    ink: new Color(colors.ink ?? '#16161d'),
    paper: new Color(colors.paper ?? '#e8ecf2'),
    accent: new Color(colors.accent ?? '#ff2a38'),
    surface: new Color(colors.surface ?? '#0b0b10'),
  };

  // --- Atlas region crop ---------------------------------------------------
  // Source rect is given as { x:0, y:0, w:512, h:320 } assuming a 1024x1024
  // atlas. UV repeat/offset transforms crop the texture to that sub-rect.
  const ATLAS_W = 1024;
  const ATLAS_H = 1024;
  const regionX = 0, regionY = 0, regionW = 512, regionH = 320;
  const aspect = regionW / regionH; // 1.6
  const cardW = 2.4;
  const cardH = cardW / aspect; // 1.5

  const group = new ctx.THREE.Group();
  group.name = 'journal-card-2';

  // Inner wrapper holds geometry so entrance animation does not fight the
  // adapter-applied scenePosition on the returned object.
  const wrap = new ctx.THREE.Group();
  group.add(wrap);

  // --- Layer 1: engineered surface backing (ink) -------------------------
  const baseGeo = new PlaneGeometry(cardW + 0.02, cardH + 0.02);
  const baseMat = new MeshBasicNodeMaterial({ color: C.ink, toneMapped: false });
  const basePlane = new Mesh(baseGeo, baseMat);
  basePlane.position.z = -0.012;
  basePlane.renderOrder = 0;
  wrap.add(basePlane);

  // --- Layer 2: grain-textured face (uses atlas region UV crop) ----------
  const faceGeo = new PlaneGeometry(cardW, cardH);
  const faceMat = new MeshBasicNodeMaterial({
    color: C.surface,
    side: DoubleSide,
    toneMapped: false,
  });
  const face = new Mesh(faceGeo, faceMat);
  face.renderOrder = 1;
  wrap.add(face);

  // --- Layer 3: accent edge bar (signal red, <=10% of frame) ------------
  const accentGeo = new PlaneGeometry(cardW, 0.03);
  const accentMat = new MeshBasicNodeMaterial({ color: C.accent, toneMapped: false });
  const accentBar = new Mesh(accentGeo, accentMat);
  accentBar.position.set(0, cardH * 0.5 - 0.015, 0.001);
  accentBar.renderOrder = 2;
  wrap.add(accentBar);

  // Subtle paper-tone vignette overlay so the dark card reads as "designed"
  // rather than flat void — a single thin inner frame outline.
  const frameGeo = new PlaneGeometry(cardW * 0.96, cardH * 0.92);
  const frameMat = new MeshBasicNodeMaterial({
    color: C.paper,
    transparent: true,
    opacity: 0.05,
    toneMapped: false,
  });
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.z = 0.0005;
  frame.renderOrder = 1;
  wrap.add(frame);

  // --- Load grain texture and apply atlas UV crop ------------------------
  const imageUrl = config.imageUrl;
  const loadedTextures = [];
  if (imageUrl) {
    const pending = ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      // Three.js Texture: bottom-left origin. Atlas source rect is top-left
      // origin, so flip Y.
      tex.repeat.set(regionW / ATLAS_W, regionH / ATLAS_H);
      tex.offset.set(regionX / ATLAS_W, 1 - (regionY + regionH) / ATLAS_H);
      tex.wrapS = THREE.ClampToEdgeWrapping;
      tex.wrapT = THREE.ClampToEdgeWrapping;
      tex.needsUpdate = true;

      faceMat.map = tex;
      faceMat.color.set('#ffffff'); // let the texture define albedo
      faceMat.needsUpdate = true;
      loadedTextures.push(tex);
    });
  }

  // --- Optional text content (spec says none here, but guarded) ----------
  // The bridging idiom — render verbatim copy if items were supplied.
  const textMeshes = [];
  for (const item of items) {
    const t = ctx.fontAtlas.createText(String(item.text ?? ''), {
      fontSize: item.typography?.fontSize ?? 0.13,
      color: item.role === 'caption' ? '#e8ecf2' : '#16161d',
      align: item.align ?? 'left',
    });
    if (t) {
      t.position.set(-cardW * 0.42, -cardH * 0.36, 0.002);
      wrap.add(t);
      textMeshes.push(t);
    }
  }

  // --- Entrance motion (weighted-settle vocabulary) ----------------------
  const tl = gsap.timeline();
  tl.from(wrap.position, { y: 0.4, duration: 0.7, ease: 'power3.out' }, 0);
  tl.from(
    wrap.scale,
    { x: 0.96, y: 0.96, z: 0.96, duration: 0.9, ease: 'power4.out' },
    0
  );
  // settle overshoot 1.04 -> 1.0
  tl.to(
    wrap.scale,
    {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.45,
      ease: 'power2.out',
      yoyo: true,
      repeat: 1,
    },
    0.7
  );

  // --- Cleanup -----------------------------------------------------------
  group.userData.cleanup = () => {
    tl.kill();
    baseGeo.dispose();
    baseMat.dispose();
    faceGeo.dispose();
    faceMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    frameGeo.dispose();
    frameMat.dispose();
    for (const t of loadedTextures) t.dispose();
  };

  group.userData.handlers = {};
  group.userData.primitiveHandles = [];

  return group;
}
